import sys

def compute_position(n, k, s, t):
    while t % n != 0:
        direction = 1 if s < k else -1
        s = (s + n + direction * (t % n)) % n
        t -= 1
    t //= n
    last_seen = [-1] * n
    remaining = t
    while remaining > 0:
        if last_seen[s] != -1:
            cycle_length = last_seen[s] - remaining
            for i in range(n):
                if last_seen[i] != -1 and last_seen[i] <= last_seen[s] and last_seen[i] % cycle_length == 0:
                    return i
            raise AssertionError()
        last_seen[s] = remaining
        for i in range(n - 1, 0, -1):
            if s < k:
                s += i
                if s >= n:
                    s -= n
            else:
                s -= i
                if s < 0:
                    s += n
        remaining -= 1
    return s

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    s = int(input_data[2]) - 1
    t = int(input_data[3])
    result = compute_position(n, k, s, t)
    print(result + 1)

if __name__ == "__main__":
    main()

